using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using MerfitCustomerApi.Domain.Entities;

namespace MerfitCustomerApi.Infrastructure.Configurations;

/// <summary>
/// WorkoutSetLog varliginin veritabani (Entity Framework Core) yapilandirmasini tanimlar.
/// </summary>
public class WorkoutSetLogConfiguration : IEntityTypeConfiguration<WorkoutSetLog>
{
    /// <summary>
    /// WorkoutSetLog varligi icin tablo adi, birincil anahtar, alan kisitlari ve iliskileri yapilandirir.
    /// </summary>
    public void Configure(EntityTypeBuilder<WorkoutSetLog> builder)
    {
        // Tablo adini belirtir.
        builder.ToTable("WorkoutSetLog", "workout");

        // Birincil anahtari tanimlar.
        builder.HasKey(x => x.Id);

        // Sette kullanilan agirlik (kilogram).
        builder.Property(x => x.WeightKg)
            .HasPrecision(18, 2);

        // Setin algilanan zorluk derecesi (RPE).
        builder.Property(x => x.Rpe)
            .HasPrecision(18, 2);

        // Sete ait notlar.
        builder.Property(x => x.Notes)
            .IsRequired(false)
            .HasMaxLength(2000);

        // RIR 0-10 araliginda; eski satirlarda bos.
        builder.ToTable(t => t.HasCheckConstraint("CK_WorkoutSetLog_Rir_Range", "\"Rir\" IS NULL OR (\"Rir\" >= 0 AND \"Rir\" <= 10)"));

        // IsWarmup / IsCompleted: eski satirlar migration'daki veritabani varsayilaniyla (false / true)
        // calisma seti ve tamamlanmis kabul edilir. Uygulama degeri her zaman acikca yazar.

        // Ayni oturum-egzersiz icin ayni set numarasi tek satirdir (ayni setin iki kez kaydi guncelleme olur).
        builder.HasIndex(x => new { x.WorkoutSessionExerciseId, x.SetNumber })
            .IsUnique();

        // Iliskiler (foreign key) yapilandirmasi.
        // Iliskili oturum-egzersiz kaydinin kimligi.
        builder.HasOne<WorkoutSessionExercise>()
            .WithMany()
            .HasForeignKey(x => x.WorkoutSessionExerciseId)
            .OnDelete(DeleteBehavior.Restrict);
    }
}
